const fs = await import('node:fs');
const path = await import('node:path');
const videoPath = globalThis.input_video_path;
const fps = globalThis.input_fps;

if (!videoPath) throw new Error('video_path is required');
if (typeof fps !== 'number' || fps <= 0) throw new Error('fps must be a positive number');

if (!fs.existsSync(videoPath)) throw new Error(`Video file not found: ${videoPath}`);

const ext = path.extname(videoPath).toLowerCase();
const validExts = ['.mp4', '.mov', '.avi', '.mkv', '.webm'];
if (!validExts.includes(ext)) throw new Error(`Unsupported video extension: ${ext}`);

globalThis.validatedVideoPath = videoPath;
globalThis.validatedFps = fps;

const { execSync } = await import('node:child_process');
const path = await import('node:path');
const fs = await import('node:fs');

const videoPath = globalThis.validatedVideoPath;
const fps = globalThis.validatedFps;

const baseName = path.basename(videoPath, path.extname(videoPath));
const slugified = baseName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const outputDir = path.join(process.cwd(), `v2p-${slugified}`);

try {
  execSync(`video2pdf "${videoPath}" -f ${fps}`, { stdio: 'pipe', timeout: 300000 });
} catch (e) {
  throw new Error(`video2pdf execution failed: ${e.message}`);
}

if (!fs.existsSync(outputDir)) throw new Error(`Output directory not found: ${outputDir}`);

const pdfPath = path.join(outputDir, 'combined-images.pdf');
if (!fs.existsSync(pdfPath)) throw new Error(`PDF file not found: ${pdfPath}`);

const files = fs.readdirSync(outputDir);
const frameCount = files.filter(f => f.endsWith('.png')).length;

globalThis.pdfPath = pdfPath;
globalThis.frameCount = frameCount;

const result = {
  pdf_path: globalThis.pdfPath,
  frame_count: globalThis.frameCount
};
console.log(JSON.stringify(result));
